"use client";

import { useMemo, useState } from "react";
import type { ReactNode } from "react";
import { APP_VERSION, RULESET_VERSION } from "@/lib/appVersion";
import { createBlankAdjudication, createBlankCase, createDemoCase } from "@/lib/caseFactory";
import { evaluateCase } from "@/lib/decisionEngine";
import type { FindingTone } from "@/lib/decisionEngine";
import { hasBlockingErrors, validateCaseInput } from "@/lib/validation";
import { projectForMode, suppressedFields } from "@/lib/modeProjection";
import { getEvidenceList } from "@/lib/evidence";
import { outstandingRapidRequirements, comprehensiveSuggestions } from "@/lib/rapidRequirements";
import { buildPriorityAlerts } from "@/lib/priorityAlerts";
import type { PriorityAlert } from "@/lib/priorityAlerts";
import { saveDraft, loadDraft, clearDraft, recordMetrics } from "@/lib/draftStorage";
import { useEffect, useRef } from "react";
import type { ValidationDomain, ValidationIssue } from "@/lib/validation";
import type { AdjudicationRecord, CaseInput, ClinicalStatus, LumbarLevel, Measurement, MotorGrade, Reflex, ReviewerAssessment, Severity, Zone } from "@/lib/schema";

const levels:LumbarLevel[]=["L3-4","L4-5","L5-S1"];
const grades:MotorGrade[]=["not-tested","5","4+","4","3","2","1","0"];
const reflexes:Reflex[]=["not-tested","normal","reduced","absent","brisk"];
const severities:Severity[]=["not-graded","none","mild","moderate","severe"];
const clinicalStatuses:ClinicalStatus[]=["not-assessed","present","absent","unknown","not-applicable"];
const steps=["Orientation","Safety","Assessment","Imaging","Plan","Review"];
const domainStep:Record<ValidationDomain,number>={orientation:0,safety:1,symptoms:2,examination:2,imaging:3,treatment:4,risk:4,research:5};

const labels:Record<string,string>={
  "not-assessed":"Not assessed","not-applicable":"Not applicable","not-measured":"Not measured","not-graded":"Not graded","not-tested":"Not tested",
  present:"Yes",absent:"No",unknown:"Unknown",lumbar:"Lumbar / lumbosacral",cervical:"Cervical",thoracic:"Thoracic",multiple:"Multiple spine regions",
  "nonspinal-uncertain":"Nonspinal or uncertain","open-to-surgery":"Open to surgery","type-1":"Type 1","type-2":"Type 2","decompression-fusion":"Decompression with fusion",
  "meaningful-temporary":"Meaningful temporary benefit","not-tried":"No injection performed","brief":"Brief benefit","sustained":"Sustained benefit","true":"Objective and reproducible","serial-objective":"Serial objective examinations","clinician-concern":"Clinician concern","patient-reported":"Patient reported",
  "right-recess":"Right lateral recess","left-recess":"Left lateral recess","right-foramen":"Right foramen","left-foramen":"Left foramen",
  "L3-4":"L3–4","L4-5":"L4–5","L5-S1":"L5–S1","not-established":"Not established","unable-to-assess":"Unable to assess","routine-reasonable":"Routine specialist review reasonable","additional-assessment":"Additional assessment needed","localization-unresolved":"Candidate localization unresolved",expedited:"Expedited specialist assessment",emergency:"Emergency pathway","factors-documented":"Fusion-rationale factors documented","incompletely-assessed":"Fusion rationale incompletely assessed","no-independent-factor":"No independent fusion factor documented","spine-surgery":"Spine surgery","consensus-meeting":"Consensus meeting",
};
const label=(value:string)=>labels[value]??value.replaceAll("-"," ").replace(/\b\w/g,c=>c.toUpperCase());
const injectionResponseLabel=(value:CaseInput["injectionResponse"])=>({unknown:"Unknown","not-tried":"No injection performed",none:"No benefit",brief:"Brief benefit","meaningful-temporary":"Meaningful temporary benefit",sustained:"Sustained benefit"}[value]);

function Card({title,children,className="",action}:{title:string;children:ReactNode;className?:string;action?:ReactNode}){return <section className={`card ${className}`}><div className="card-heading"><div className="card-title">{title}</div>{action}</div>{children}</section>}
function Field({label:fieldLabel,children,hint,required,fieldId}:{label:string;children:ReactNode;hint?:string;required?:string;fieldId?:string}){return <label className="field" data-field={fieldId}><span>{fieldLabel}{required&&<em>{required}</em>}</span>{children}{hint&&<small>{hint}</small>}</label>}
function Select<T extends string>({value,options,onChange}:{value:T;options:readonly T[];onChange:(v:T)=>void}){return <select value={value} onChange={e=>onChange(e.target.value as T)}>{options.map(x=><option key={x} value={x}>{label(x)}</option>)}</select>}
function StatusField({label:fieldLabel,value,onChange,hint,allowNA=false}:{label:string;value:ClinicalStatus;onChange:(v:ClinicalStatus)=>void;hint?:string;allowNA?:boolean}){const options=allowNA?clinicalStatuses:clinicalStatuses.filter(x=>x!=="not-applicable");return <Field label={fieldLabel} hint={hint}><Select value={value} options={options} onChange={onChange}/></Field>}
function MeasurementField({label:fieldLabel,m,onChange,min,max,step=1,hint}:{label:string;m:Measurement;onChange:(m:Measurement)=>void;min?:number;max?:number;step?:number;hint?:string}){
  const invalid=m.status==="measured"&&(m.value===null||(min!==undefined&&m.value<min)||(max!==undefined&&m.value>max));
  return <Field label={fieldLabel} hint={hint}><div className={`measurement ${invalid?"invalid":""}`}><select value={m.status} onChange={e=>onChange({...m,status:e.target.value as Measurement["status"],value:e.target.value==="measured"?m.value:null})}>{["not-measured","measured","unknown","not-applicable"].map(x=><option key={x} value={x}>{label(x)}</option>)}</select>{m.status==="measured"&&<div className="value-with-unit"><input type="number" value={m.value??""} min={min} max={max} step={step} onChange={e=>onChange({...m,value:e.target.value===""?null:Number(e.target.value)})}/><span>{m.unit}</span></div>}</div>{invalid&&<small className="inline-error">Enter a value within {min}–{max}.</small>}</Field>
}
function ToneBadge({tone,children}:{tone:FindingTone;children:ReactNode}){return <span className={`tone-badge tone-${tone}`}>{children}</span>}
function List({items,emptyText}:{items:string[];emptyText?:string}){return items.length?<ul className="finding-list">{items.map((x,i)=><li key={`${x}-${i}`}>{x}</li>)}</ul>:emptyText?<p className="muted">{emptyText}</p>:null}
function IssuePanel({issues,onJump}:{issues:ValidationIssue[];onJump:(issue:ValidationIssue)=>void}){if(!issues.length)return <div className="validation-clear"><b>Ready</b><span>No data-integrity issues were detected.</span></div>;return <div className="issue-stack">{issues.map(issue=><button type="button" key={issue.id} className={`issue issue-${issue.severity}`} onClick={()=>onJump(issue)}><span className="issue-icon">{issue.severity==="error"?"!":issue.severity==="warning"?"△":"i"}</span><span><b>{issue.title}</b><small>{issue.message}</small>{issue.action&&<em>{issue.action}</em>}</span></button>)}</div>}

function ReviewerForm({title,value,onChange}:{title:string;value:ReviewerAssessment;onChange:(v:ReviewerAssessment)=>void}){
 const set=<K extends keyof ReviewerAssessment>(k:K,v:ReviewerAssessment[K])=>onChange({...value,[k]:v});
 return <Card title={title}><div className="grid three"><Field label="Reviewer ID"><input value={value.reviewerId} onChange={e=>set("reviewerId",e.target.value)}/></Field><Field label="Specialty"><Select value={value.specialty} options={["not-entered","spine-surgery","pmr","pain","radiology","other"] as const} onChange={v=>set("specialty",v)}/></Field><Field label="Confidence"><Select value={value.confidence} options={["not-assessed","low","moderate","high"] as const} onChange={v=>set("confidence",v)}/></Field><Field label="Syndrome"><Select value={value.syndrome} options={["not-entered","radiculopathy","claudication","mixed","axial","indeterminate"] as const} onChange={v=>set("syndrome",v)}/></Field><Field label="Side"><Select value={value.side} options={["not-entered","right","left","bilateral","midline","not-assessed"] as const} onChange={v=>set("side",v)}/></Field><Field label="Root"><Select value={value.root} options={["not-entered","L4","L5","S1","multiroot","none","not-assessed"] as const} onChange={v=>set("root",v)}/></Field><Field label="Level"><Select value={value.level} options={["not-entered",...levels,"multilevel","none"] as const} onChange={v=>set("level",v)}/></Field><Field label="Zone"><Select value={value.zone} options={["not-entered","central","right-recess","left-recess","right-foramen","left-foramen","multilevel","none"] as const} onChange={v=>set("zone",v)}/></Field><Field label="Urgency"><Select value={value.urgency} options={["not-entered","emergency","urgent","routine","indeterminate"] as const} onChange={v=>set("urgency",v)}/></Field><Field label="Additional testing"><Select value={value.additionalTesting} options={["not-entered","yes","no","indeterminate"] as const} onChange={v=>set("additionalTesting",v)}/></Field><Field label="Specialist review"><Select value={value.specialistReviewSupport} options={["not-entered","supported","not-established","unable-to-assess"] as const} onChange={v=>set("specialistReviewSupport",v)}/></Field><Field label="Fusion rationale"><Select value={value.fusionRationale} options={["not-entered","established","possible","not-established","unable-to-assess"] as const} onChange={v=>set("fusionRationale",v)}/></Field></div><Field label="Rationale"><textarea value={value.rationale} onChange={e=>set("rationale",e.target.value)}/></Field></Card>
}

export default function SpineDecisionApp(){
 const [data,setData]=useState<CaseInput>(()=>createBlankCase());
 const [adjudication,setAdjudication]=useState<AdjudicationRecord>(()=>createBlankAdjudication());
 const [view,setView]=useState<"entry"|"results"|"literature"|"research">("entry");
 const [step,setStep]=useState(0);
 const [demo,setDemo]=useState(false);
 const [workflowMode,setWorkflowMode]=useState<"rapid"|"comprehensive">("rapid");
 const [advancedExam,setAdvancedExam]=useState(false);
 const [advancedRisk,setAdvancedRisk]=useState(false);
 const [activeLevels,setActiveLevels]=useState<LumbarLevel[]>([]);
 const [warningsAcknowledged,setWarningsAcknowledged]=useState(false);
 const [generatedWorkflowMode,setGeneratedWorkflowMode]=useState<"rapid"|"comprehensive">("rapid");
 const [rapidCesStatus,setRapidCesStatus]=useState<ClinicalStatus>("not-assessed");
 const [rapidSeriousStatus,setRapidSeriousStatus]=useState<ClinicalStatus>("not-assessed");
 const [rapidMotorStatus,setRapidMotorStatus]=useState<ClinicalStatus>("not-assessed");
 const [rapidMotorSide,setRapidMotorSide]=useState<"not-assessed"|"right"|"left"|"bilateral">("not-assessed");
 const [rapidMotorRoot,setRapidMotorRoot]=useState<"not-assessed"|"L4"|"L5"|"S1">("not-assessed");
 const [rapidMotorGrade,setRapidMotorGrade]=useState<MotorGrade>("not-tested");
 const [rapidImagingStatus,setRapidImagingStatus]=useState<ClinicalStatus>("not-assessed");
 const [rapidImagingLevel,setRapidImagingLevel]=useState<LumbarLevel|"not-assessed">("not-assessed");
 const [rapidImagingZone,setRapidImagingZone]=useState<Zone|"not-assessed">("not-assessed");
 const [rapidImagingSeverity,setRapidImagingSeverity]=useState<Severity>("not-graded");
 const [generatedIssues,setGeneratedIssues]=useState<ValidationIssue[]>([]);
 const [copyState,setCopyState]=useState<"idle"|"copied"|"failed">("idle");
 const [draftSavedAt,setDraftSavedAt]=useState<string|null>(null);
 const [recoverable,setRecoverable]=useState<{savedAt:string}|null>(null);
 const [confirmClear,setConfirmClear]=useState(false);
 const [generatedAt,setGeneratedAt]=useState<string|null>(null);
 const startedAt=useRef<string>(new Date().toISOString());
 const editCount=useRef(0);
 const modeSwitches=useRef(0);
 const [snapshot,setSnapshot]=useState<CaseInput|null>(null);
 const [result,setResult]=useState<ReturnType<typeof evaluateCase>|null>(null);
 const engineInput=useMemo(()=>projectForMode(data,workflowMode),[data,workflowMode]);
 const issues=useMemo(()=>validateCaseInput(engineInput),[engineInput]);
 useEffect(()=>{const d=loadDraft();if(d)setRecoverable({savedAt:d.savedAt})},[]);
 useEffect(()=>{const t=setTimeout(()=>{const at=saveDraft(data,workflowMode);if(at)setDraftSavedAt(at)},1200);return ()=>clearTimeout(t)},[data,workflowMode]);
 const suppressed=useMemo(()=>suppressedFields(data,workflowMode),[data,workflowMode]);
 // Safety state is derived continuously from the live case so an emergency is never hidden
 // behind unresolved validation errors. Blocking errors must stop the routine synthesis,
 // not stop the clinician from being told the case looks like an emergency.
 const liveSafety=useMemo(()=>evaluateCase(engineInput),[engineInput]);
 const outstanding=useMemo(()=>outstandingRapidRequirements(engineInput),[engineInput]);
 const suggestions=useMemo(()=>comprehensiveSuggestions(engineInput),[engineInput]);
 const outOfScope=data.lumbarScopeConfirmed==="no"||data.lumbarScopeConfirmed==="uncertain";
 const errors=issues.filter(x=>x.severity==="error"), warnings=issues.filter(x=>x.severity==="warning"), infos=issues.filter(x=>x.severity==="info");
 const set=<K extends keyof CaseInput>(key:K,value:CaseInput[K])=>{editCount.current+=1;setData(p=>({...p,[key]:value}));setWarningsAcknowledged(false)};
 const switchMode=(m:"rapid"|"comprehensive")=>{if(m!==workflowMode)modeSwitches.current+=1;setWorkflowMode(m)};
 const setRapidCes=(value:ClinicalStatus)=>{setRapidCesStatus(value);if(value!=="present")setData(p=>({...p,urinaryRetention:value,urinarySensationLoss:value,urinaryInitiationDifficulty:value,overflowIncontinence:value,saddleSensoryChange:value}));setWarningsAcknowledged(false)};
 const setRapidSerious=(value:ClinicalStatus)=>{setRapidSeriousStatus(value);if(value!=="present")setData(p=>({...p,feverOrSystemicInfection:value,cancerWarning:value,traumaOrFractureWarning:value}));setWarningsAcknowledged(false)};
 const clearRapidMotor=()=>setData(p=>({...p,rightKneeExtension:"not-tested",leftKneeExtension:"not-tested",rightAnkleDorsiflexion:"not-tested",leftAnkleDorsiflexion:"not-tested",rightGreatToeExtension:"not-tested",leftGreatToeExtension:"not-tested",rightPlantarFlexion:"not-tested",leftPlantarFlexion:"not-tested",weaknessQuality:"not-assessed",examConfidence:"not-assessed"}));
 const setRapidMotorFinding=(value:ClinicalStatus)=>{setRapidMotorStatus(value);setData(p=>({...p,rapidMotorScreen:value}));if(value!=="present"){setRapidMotorSide("not-assessed");setRapidMotorRoot("not-assessed");setRapidMotorGrade("not-tested");clearRapidMotor()}setWarningsAcknowledged(false)};
 const applyRapidMotor=(side:typeof rapidMotorSide,root:typeof rapidMotorRoot,grade:MotorGrade)=>{setRapidMotorStatus("present");setRapidMotorSide(side);setRapidMotorRoot(root);setRapidMotorGrade(grade);setData(p=>{const next={...p,rapidMotorScreen:"present",rightKneeExtension:"not-tested",leftKneeExtension:"not-tested",rightAnkleDorsiflexion:"not-tested",leftAnkleDorsiflexion:"not-tested",rightGreatToeExtension:"not-tested",leftGreatToeExtension:"not-tested",rightPlantarFlexion:"not-tested",leftPlantarFlexion:"not-tested",weaknessQuality:"true"} as CaseInput;if(side==="not-assessed"||root==="not-assessed"||grade==="not-tested")return next;const sides=side==="bilateral"?["right","left"] as const:[side] as const;for(const s of sides){if(root==="L4")next[`${s}KneeExtension` as "rightKneeExtension"] = grade;if(root==="L5"){next[`${s}AnkleDorsiflexion` as "rightAnkleDorsiflexion"] = grade;next[`${s}GreatToeExtension` as "rightGreatToeExtension"] = grade}if(root==="S1")next[`${s}PlantarFlexion` as "rightPlantarFlexion"] = grade}return next});setWarningsAcknowledged(false)};
 const clearRapidImaging=()=>{setActiveLevels([]);setData(p=>({...p,levelByLevelDocumented:"absent",imagingMatrix:createBlankCase().imagingMatrix}));};
 const setRapidImagingFinding=(value:ClinicalStatus)=>{setRapidImagingStatus(value);setData(p=>({...p,rapidImagingScreen:value}));if(value!=="present"){setRapidImagingLevel("not-assessed");setRapidImagingZone("not-assessed");setRapidImagingSeverity("not-graded");clearRapidImaging()}setWarningsAcknowledged(false)};
 const applyRapidImaging=(level:LumbarLevel|"not-assessed",zone:Zone|"not-assessed",severity:Severity)=>{setRapidImagingStatus("present");setRapidImagingLevel(level);setRapidImagingZone(zone);setRapidImagingSeverity(severity);if(level==="not-assessed")return;setActiveLevels([level]);setData(p=>({...p,rapidImagingScreen:"present",levelByLevelDocumented:"present",imagingMatrix:createBlankCase().imagingMatrix.map(row=>{if(row.level!==level)return row;const next={...row,central:"not-graded",rightRecess:"not-graded",leftRecess:"not-graded",rightForamen:"not-graded",leftForamen:"not-graded"} as typeof row;if(zone!=="not-assessed"&&severity!=="not-graded"){const key={central:"central","right-recess":"rightRecess","left-recess":"leftRecess","right-foramen":"rightForamen","left-foramen":"leftForamen"}[zone] as "central";next[key]=severity}return next})}));setWarningsAcknowledged(false)};
 const updateLevel=<K extends keyof CaseInput["imagingMatrix"][number]>(level:LumbarLevel,key:K,value:CaseInput["imagingMatrix"][number][K])=>set("imagingMatrix",data.imagingMatrix.map(x=>x.level===level?{...x,[key]:value}:x));
 const updateFusion=<K extends keyof CaseInput["fusionMatrix"][number]>(level:LumbarLevel,key:K,value:CaseInput["fusionMatrix"][number][K])=>set("fusionMatrix",data.fusionMatrix.map(x=>x.level===level?{...x,[key]:value}:x));
 const jump=(issue:ValidationIssue)=>{setView("entry");setStep(domainStep[issue.domain]);setTimeout(()=>document.querySelector(`[data-field="${issue.field??""}"]`)?.scrollIntoView({behavior:"smooth",block:"center"}),50)};
 const generate=()=>{if(hasBlockingErrors(issues))return;if(warnings.length&&!warningsAcknowledged)return;const snap=structuredClone(engineInput);setSnapshot(snap);setGeneratedIssues(structuredClone(issues));setGeneratedWorkflowMode(workflowMode);const at=new Date().toISOString();setGeneratedAt(at);setResult(evaluateCase(snap));
  recordMetrics({startedAt:startedAt.current,generatedAt:at,elapsedSeconds:Math.round((Date.parse(at)-Date.parse(startedAt.current))/1000),mode:workflowMode,fieldEdits:editCount.current,confirmationsAnswered:18-outstanding.length,modeSwitches:modeSwitches.current,blockingAlerts:issues.filter(x=>x.severity==="error").length,importantAlerts:issues.filter(x=>x.severity==="warning").length,clinicianAgreed:"not-recorded"});
  setView("results");window.scrollTo({top:0,behavior:"smooth"})};
 const reset=()=>{clearDraft();setRecoverable(null);setDraftSavedAt(null);setGeneratedAt(null);setConfirmClear(false);startedAt.current=new Date().toISOString();editCount.current=0;setData(createBlankCase());setAdjudication(createBlankAdjudication());setDemo(false);setStep(0);setView("entry");setSnapshot(null);setResult(null);setActiveLevels([]);setRapidCesStatus("not-assessed");setRapidSeriousStatus("not-assessed");setRapidMotorStatus("not-assessed");setRapidMotorSide("not-assessed");setRapidMotorRoot("not-assessed");setRapidMotorGrade("not-tested");setRapidImagingStatus("not-assessed");setRapidImagingLevel("not-assessed");setRapidImagingZone("not-assessed");setRapidImagingSeverity("not-graded")};
 const loadDemo=()=>{const d=createDemoCase();setData(d);setDemo(true);setActiveLevels(["L4-5"]);setStep(0);setView("entry")};
 const updateAdjudication=<K extends keyof AdjudicationRecord>(k:K,v:AdjudicationRecord[K])=>setAdjudication(p=>({...p,[k]:v}));
 const exportJson=()=>{const blob=new Blob([JSON.stringify({assessment:snapshot,result,adjudication,validationIssues:generatedIssues,workflowMode:generatedWorkflowMode,suppressedInRapidMode:suppressedFields(data,generatedWorkflowMode),fullEnteredCase:data,appVersion:APP_VERSION,rulesetVersion:RULESET_VERSION},null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`spinedx-${adjudication.caseId||data.studyId||"case"}.json`;a.click();URL.revokeObjectURL(a.href)};
 const printSummary=()=>window.print();
 const buildHandoff=()=>{if(!result)return "";const target=result.targets[0];
  const uncertainty=[...result.missing,...result.scopeNotes].slice(0,4);
  return [
   `SpineDx-Tx ${generatedWorkflowMode==="rapid"?"PRELIMINARY RAPID SYNTHESIS":"clinical synthesis"} (ruleset ${RULESET_VERSION})`,
   `Generated from assessment snapshot at ${generatedAt?new Date(generatedAt).toLocaleString():"unknown time"}`,
   generatedWorkflowMode==="rapid"?"Limited rapid review. Not a complete neurologic examination or complete imaging review.":"",
   "",
   `Clinical problem: ${label(result.syndrome.derived)}`,
   `Candidate localization: ${target?`${label(target.side)} ${target.root}, ${target.level} ${label(target.zone)}`:"not established on current information"}`,
   `Immediate priority: ${label(result.urgency)} — ${result.urgencyReason}`,
   `Recommended action: ${result.nextSteps[0]??result.specialistReview.reasons[0]??"Clinical review required"}`,
   `Major uncertainty: ${uncertainty.length?uncertainty.join(" | "):"none recorded"}`,
   "",
   "Clinician confirmation required. This framework does not make an autonomous diagnosis or treatment decision and is not clinically validated.",
  ].filter(x=>x!=="" || true).join("\n")};
 const copySummary=async()=>{const text=buildHandoff();if(!text)return;try{await navigator.clipboard.writeText(text);setCopyState("copied")}catch{setCopyState("failed")}finally{setTimeout(()=>setCopyState("idle"),2500)}};
 const showRadicular=data.clinicianPhenotype==="radicular"||data.clinicianPhenotype==="mixed"||data.legDominantPain==="present"||data.dermatomalPain==="present";
 const showClaudication=data.clinicianPhenotype==="claudication"||data.clinicianPhenotype==="mixed"||data.walkingProvokes==="present"||data.standingProvokes==="present";
 const showFusion=data.proposedProcedure==="fusion"||data.proposedProcedure==="decompression-fusion";
 const showInjectionTarget=!(["unknown","not-tried"] as const).includes(data.injectionResponse as "unknown"|"not-tried");
 const toggleLevel=(level:LumbarLevel)=>{
  if(activeLevels.includes(level)){
    const blank=createBlankCase().imagingMatrix.find(x=>x.level===level)!;
    const next=activeLevels.filter(x=>x!==level);
    setData(p=>({...p,imagingMatrix:p.imagingMatrix.map(x=>x.level===level?blank:x),levelByLevelDocumented:next.length?"present":"absent"}));
    setActiveLevels(next);
    setWarningsAcknowledged(false);
  } else {
    setActiveLevels(p=>[...p,level]);
    set("levelByLevelDocumented","present");
  }
};

 return <main>
  <header className="topbar"><div><div className="brand-mark">S</div><div><h1>SpineDx-Tx</h1><p>Lumbar clinical–imaging reconciliation</p></div></div><div className="header-actions"><span className="version">v{APP_VERSION}</span><button onClick={loadDemo}>Load demo</button><button onClick={reset}>New case</button></div></header>
  {demo&&<div className="demo-banner">Demonstration case — not patient data.</div>}
  {recoverable&&<div className="draft-bar"><div><b>An unsaved draft from {new Date(recoverable.savedAt).toLocaleString()} was found.</b><span>Prototype local draft storage. Do not enter directly identifying patient information. This is not authenticated or HIPAA-compliant storage.</span></div><div className="draft-actions"><button type="button" onClick={()=>{const d=loadDraft();if(d){setData(d.data);setWorkflowMode(d.mode)}setRecoverable(null)}}>Resume draft</button><button type="button" onClick={()=>setConfirmClear(true)}>Discard</button></div></div>}
  {confirmClear&&<div className="draft-bar confirm" role="alertdialog"><div><b>Discard the saved draft?</b><span>This cannot be undone.</span></div><div className="draft-actions"><button type="button" className="danger" onClick={()=>{clearDraft();setRecoverable(null);setConfirmClear(false)}}>Yes, discard</button><button type="button" onClick={()=>setConfirmClear(false)}>Cancel</button></div></div>}
  {(liveSafety.urgency==="emergency"||liveSafety.urgency==="urgent")&&<div className={`safety-alert ${liveSafety.urgency}`} role="alert"><b>{liveSafety.urgency==="emergency"?"Emergency warning feature recorded":"Expedited assessment supported"}</b><span>{liveSafety.urgencyReason}</span><em>This alert is shown from the entered data and does not depend on completing the rest of the assessment. The app cannot exclude emergency pathology.</em></div>}
  <nav className="mode-nav"><button className={view==="entry"?"active":""} onClick={()=>setView("entry")}>Clinical assessment</button><button className={view==="results"?"active":""} disabled={!result} onClick={()=>result&&setView("results")}>Clinical synthesis</button><button className={view==="literature"?"active":""} onClick={()=>setView("literature")}>Evidence</button><button className={view==="research"?"active":""} onClick={()=>setView("research")}>Research workspace</button></nav>
  {view==="entry"&&<section className="value-workflow"><div className="workflow-copy"><small>Physician workflow</small><h2>{workflowMode==="rapid"?"Rapid review":"Comprehensive review"}</h2><p>{workflowMode==="rapid"?"Complete a brief safety, syndrome, motor, imaging, and treatment-context check. Expand only when the case requires it.":"Use the full structured assessment for complex cases, validation, or research-quality documentation."}</p></div><div className="workflow-toggle"><button className={workflowMode==="rapid"?"active":""} onClick={()=>switchMode("rapid")}>Rapid review</button><button className={workflowMode==="comprehensive"?"active":""} onClick={()=>switchMode("comprehensive")}>Comprehensive</button></div><div className="value-pill"><b>Save time</b><span>Fewer confirmations for uncomplicated lumbar presentations.</span></div><div className="value-pill"><b>Catch issues</b><span>Surface unresolved safety, side, level, and treatment-target conflicts.</span></div><div className="value-pill"><b>Communicate</b><span>Generate a standardized note-ready handoff.</span></div></section>}
  {view==="entry"&&workflowMode==="rapid"&&<div className="rapid-status"><div className="rapid-count"><b>{outstanding.length===0?"All required confirmations complete":`${outstanding.length} required confirmation${outstanding.length===1?"":"s"} remaining`}</b>{outstanding.length>0&&<span>{outstanding.slice(0,4).map(r=>r.label).join(" · ")}{outstanding.length>4?` · +${outstanding.length-4} more`:""}</span>}</div><p className="rapid-scope">Rapid review supports safety screening, basic syndrome classification, major discordance detection, and preliminary localization. It is not a complete neurologic or multilevel imaging assessment.</p></div>}
  {view==="entry"&&workflowMode==="rapid"&&suggestions.length>0&&<div className="escalation-suggestion"><div><b>Comprehensive review is recommended for this case.</b><span>{suggestions[0]}{suggestions.length>1?` (and ${suggestions.length-1} other factor${suggestions.length>2?"s":""})`:""}</span></div><button type="button" onClick={()=>switchMode("comprehensive")}>Switch to Comprehensive</button></div>}
  {view==="entry"&&outOfScope&&<div className="scope-block" role="alert"><b>This case is outside the current lumbar/lumbosacral module. A region-specific assessment is required.</b><span>General safety documentation may continue. Lumbar localization, decompression, fusion, and treatment synthesis are withheld.</span></div>}
  {view==="entry"&&workflowMode==="rapid"&&suppressed.length>0&&<div className="suppressed-notice"><b>{suppressed.length} previously entered field(s) are not used in Rapid review</b><span>They are preserved and will be reinstated in Comprehensive review, but they are excluded from the rapid conclusion so that hidden data cannot influence it.</span><button type="button" onClick={()=>switchMode("comprehensive")}>Switch to Comprehensive</button></div>}

  {view==="entry"&&<div className="workspace"><aside className="stepper">{steps.map((x,i)=><button key={x} className={step===i?"active":step>i?"done":""} disabled={outOfScope&&i>=2&&i<=4} onClick={()=>setStep(i)}><span>{i+1}</span>{x}{issues.some(v=>domainStep[v.domain]===i&&v.severity==="error")&&<b className="step-alert">!</b>}</button>)}</aside><section className="content">
   <div className="section-head"><div><small>Step {step+1} of {steps.length}</small><h2>{steps[step]}</h2></div><p>{step===0?"Document the patient’s primary lumbar presentation and functional goal.":step===1?"Complete the minimum safety screen before interpreting urgency.":step===2?"Only syndrome-relevant questions are shown.":step===3?"Expand only levels that may be clinically relevant.":step===4?"Treatment and risk fields appear only when applicable.":"Resolve data-quality issues before synthesis."}</p></div>

   {step===0&&(workflowMode==="rapid"?<Card title="Rapid orientation"><div className="module-scope"><div><small>Active clinical module</small><strong>Lumbar / lumbosacral</strong></div><p>Four core items establish the presenting context.</p></div><div className="grid two"><Field label="Is the current assessment primarily lumbar/lumbosacral?"><Select value={data.lumbarScopeConfirmed} options={["not-assessed","yes","no","uncertain"] as const} onChange={v=>set("lumbarScopeConfirmed",v)}/></Field><Field label="Main symptom pattern"><Select value={data.clinicianPhenotype} options={["not-assessed","radicular","claudication","mixed","axial","uncertain"] as const} onChange={v=>set("clinicianPhenotype",v)}/></Field><Field label="Side"><Select value={data.side} options={["not-assessed","right","left","bilateral","midline"] as const} onChange={v=>set("side",v)}/></Field><MeasurementField label="Symptom duration" m={data.symptomDurationWeeks} onChange={v=>set("symptomDurationWeeks",v)} min={0} max={1000}/><Field label="Patient’s main goal"><input value={data.patientGoal} onChange={e=>set("patientGoal",e.target.value)} placeholder="e.g., walk 20 minutes, reduce leg pain"/></Field></div><p className="rapid-note">Age, treatment preference, and outcomes remain available in Comprehensive review when they are needed.</p></Card>:<><Card title="Clinical orientation"><div className="module-scope"><div><small>Active clinical module</small><strong>Lumbar / lumbosacral</strong></div><p>Other spinal regions are outside the scope of this version.</p></div><div className="grid three"><Field label="Is the current assessment primarily lumbar/lumbosacral?" hint="Only the lumbar/lumbosacral module exists in this build."><Select value={data.lumbarScopeConfirmed} options={["not-assessed","yes","no","uncertain"] as const} onChange={v=>set("lumbarScopeConfirmed",v)}/></Field><MeasurementField label="Age" m={data.age} onChange={v=>set("age",v)} min={0} max={120}/><Field label="Main symptom pattern"><Select value={data.clinicianPhenotype} options={["not-assessed","radicular","claudication","mixed","axial","uncertain"] as const} onChange={v=>set("clinicianPhenotype",v)}/></Field><Field label="Side"><Select value={data.side} options={["not-assessed","right","left","bilateral","midline"] as const} onChange={v=>set("side",v)}/></Field><MeasurementField label="Symptom duration" m={data.symptomDurationWeeks} onChange={v=>set("symptomDurationWeeks",v)} min={0} max={1000}/><Field label="Patient’s main goal"><input value={data.patientGoal} onChange={e=>set("patientGoal",e.target.value)} placeholder="e.g., walk 20 minutes, reduce leg pain"/></Field><Field label="Treatment preference"><Select value={data.treatmentPreference} options={["not-assessed","nonoperative","open-to-surgery","undecided"] as const} onChange={v=>set("treatmentPreference",v)}/></Field></div><details className="conditional"><summary>Scope exclusions — conditions outside this module</summary><p className="muted">A positive answer places the case outside the lumbar reconciliation module. Safety screening still applies, but localization and treatment output is withheld.</p><div className="grid three"><StatusField label="Pregnant?" value={data.pregnant} onChange={v=>set("pregnant",v)} allowNA/><StatusField label="Cervical or thoracic symptoms?" value={data.cervicalThoracicSymptoms} onChange={v=>set("cervicalThoracicSymptoms",v)}/><StatusField label="Neuromuscular disease?" value={data.neuromuscularDisease} onChange={v=>set("neuromuscularDisease",v)}/><StatusField label="Known tumour?" value={data.knownTumor} onChange={v=>set("knownTumor",v)}/><StatusField label="Known spinal infection?" value={data.knownInfection} onChange={v=>set("knownInfection",v)}/><StatusField label="Acute fracture?" value={data.acuteFracture} onChange={v=>set("acuteFracture",v)}/><StatusField label="Major deformity?" value={data.majorDeformity} onChange={v=>set("majorDeformity",v)}/><StatusField label="Prior long fusion?" value={data.priorLongFusion} onChange={v=>set("priorLongFusion",v)}/><StatusField label="Predominantly axial pain?" value={data.predominantlyAxialPain} onChange={v=>set("predominantlyAxialPain",v)}/></div></details></Card></>)}

   {step===1&&(workflowMode==="rapid"?<><Card title="Rapid safety screen" className="safety-card"><p className="section-intro">Three confirmations cover the minimum safety screen. A positive answer expands the specific findings.</p><div className="grid four"><StatusField label="New bladder or saddle symptoms?" value={rapidCesStatus} onChange={setRapidCes} hint="Retention, loss of urinary sensation, difficulty initiating, overflow, or saddle sensory change."/><StatusField label="Severe bilateral leg weakness or numbness?" value={data.bilateralSevereDeficit} onChange={v=>set("bilateralSevereDeficit",v)} hint="Asked separately from bladder symptoms; it is a distinct red flag with a distinct examination basis."/><StatusField label="New or progressive weakness?" value={data.progressiveWeakness} onChange={v=>set("progressiveWeakness",v)}/><StatusField label="Concern for infection, cancer, fracture, or major trauma?" value={rapidSeriousStatus} onChange={setRapidSerious}/></div></Card>{rapidCesStatus==="present"&&<Card title="Specify neurologic warning"><div className="grid three"><StatusField label="New urinary retention?" value={data.urinaryRetention} onChange={v=>set("urinaryRetention",v)}/><StatusField label="Loss of urinary sensation?" value={data.urinarySensationLoss} onChange={v=>set("urinarySensationLoss",v)}/><StatusField label="Difficulty initiating urination?" value={data.urinaryInitiationDifficulty} onChange={v=>set("urinaryInitiationDifficulty",v)}/><StatusField label="Overflow incontinence?" value={data.overflowIncontinence} onChange={v=>set("overflowIncontinence",v)}/><StatusField label="Saddle sensory change?" value={data.saddleSensoryChange} onChange={v=>set("saddleSensoryChange",v)}/></div></Card>}{rapidSeriousStatus==="present"&&<Card title="Specify serious-pathology concern"><div className="grid three"><StatusField label="Infection warning features?" value={data.feverOrSystemicInfection} onChange={v=>set("feverOrSystemicInfection",v)}/><StatusField label="Cancer warning features?" value={data.cancerWarning} onChange={v=>set("cancerWarning",v)}/><StatusField label="Major trauma or fracture concern?" value={data.traumaOrFractureWarning} onChange={v=>set("traumaOrFractureWarning",v)}/></div></Card>}{data.progressiveWeakness==="present"&&<Card title="Progression detail"><div className="grid two"><Field label="Basis of progression"><Select value={data.weaknessProgressionBasis} options={["not-assessed","patient-reported","clinician-concern","serial-objective"] as const} onChange={v=>set("weaknessProgressionBasis",v)}/></Field><Field label="Trajectory"><Select value={data.weaknessTrajectory} options={["not-assessed","stable","improving","progressive"] as const} onChange={v=>set("weaknessTrajectory",v)}/></Field></div></Card>}</>:<><Card title="Bladder, bowel, and saddle symptoms" className="safety-card"><div className="grid three"><StatusField label="New urinary retention?" value={data.urinaryRetention} onChange={v=>set("urinaryRetention",v)}/><StatusField label="Loss of urinary sensation?" value={data.urinarySensationLoss} onChange={v=>set("urinarySensationLoss",v)}/><StatusField label="Difficulty initiating urination?" value={data.urinaryInitiationDifficulty} onChange={v=>set("urinaryInitiationDifficulty",v)}/><StatusField label="Overflow incontinence?" value={data.overflowIncontinence} onChange={v=>set("overflowIncontinence",v)}/><StatusField label="Saddle sensory change?" value={data.saddleSensoryChange} onChange={v=>set("saddleSensoryChange",v)}/><StatusField label="Severe bilateral deficit?" value={data.bilateralSevereDeficit} onChange={v=>set("bilateralSevereDeficit",v)}/></div></Card><Card title="Neurologic deterioration and serious pathology"><div className="grid three"><StatusField label="New or progressive weakness?" value={data.progressiveWeakness} onChange={v=>set("progressiveWeakness",v)}/>{data.progressiveWeakness==="present"&&<Field label="Basis of progression"><Select value={data.weaknessProgressionBasis} options={["not-assessed","patient-reported","clinician-concern","serial-objective"] as const} onChange={v=>set("weaknessProgressionBasis",v)}/></Field>}<StatusField label="Infection warning features?" value={data.feverOrSystemicInfection} onChange={v=>set("feverOrSystemicInfection",v)}/><StatusField label="Cancer warning features?" value={data.cancerWarning} onChange={v=>set("cancerWarning",v)}/><StatusField label="Major trauma or fracture concern?" value={data.traumaOrFractureWarning} onChange={v=>set("traumaOrFractureWarning",v)}/></div></Card></>)}

   {step===2&&(workflowMode==="rapid"?<><Card title="Rapid syndrome check"><div className="grid three"><StatusField label="Leg symptoms more important than back pain?" value={data.legDominantPain} onChange={v=>set("legDominantPain",v)}/><StatusField label="Dermatomal pain or paresthesia?" value={data.dermatomalPain} onChange={v=>set("dermatomalPain",v)}/><Field label="Straight-leg raise"><Select value={data.straightLegRaise} options={["not-tested","negative","positive"] as const} onChange={v=>set("straightLegRaise",v)}/></Field></div>{showClaudication&&<div className="rapid-branch"><b>Claudication pattern</b><div className="grid three"><StatusField label="Provoked by standing or walking?" value={data.walkingProvokes} onChange={v=>{set("walkingProvokes",v);set("standingProvokes",v)}}/><StatusField label="Relieved by sitting or flexion?" value={data.sittingRelieves} onChange={v=>{set("sittingRelieves",v);set("flexionRelieves",v)}}/><StatusField label="Vascular concern on pulse examination?" value={data.pulsesAbnormal} onChange={v=>set("pulsesAbnormal",v)}/></div></div>}</Card><Card title="Focused motor screen"><p className="section-intro">Confirm whether a reproducible focal motor deficit is present. Enter details only when abnormal.</p><div className="grid two"><StatusField label="Objective focal motor deficit?" value={rapidMotorStatus} onChange={setRapidMotorFinding}/></div>{rapidMotorStatus==="present"&&<div className="grid four rapid-branch"><Field label="Side"><Select value={rapidMotorSide} options={["not-assessed","right","left","bilateral"] as const} onChange={v=>applyRapidMotor(v,rapidMotorRoot,rapidMotorGrade)}/></Field><Field label="Root pattern"><Select value={rapidMotorRoot} options={["not-assessed","L4","L5","S1"] as const} onChange={v=>applyRapidMotor(rapidMotorSide,v,rapidMotorGrade)}/></Field><Field label="Lowest reliable grade"><Select value={rapidMotorGrade} options={grades.filter(x=>x!=="5")} onChange={v=>applyRapidMotor(rapidMotorSide,rapidMotorRoot,v)}/></Field><Field label="Exam reliability"><Select value={data.examConfidence} options={["not-assessed","low","moderate","high"] as const} onChange={v=>set("examConfidence",v)}/></Field></div>}</Card></>:<><Card title="Symptom pattern"><div className="grid three"><StatusField label="Leg pain more important than back pain?" value={data.legDominantPain} onChange={v=>set("legDominantPain",v)}/><StatusField label="Dermatomal pain or paresthesia?" value={data.dermatomalPain} onChange={v=>set("dermatomalPain",v)}/><MeasurementField label="Leg pain NRS" m={data.legPainNrs} onChange={v=>set("legPainNrs",v)} min={0} max={10}/><MeasurementField label="Back pain NRS" m={data.backPainNrs} onChange={v=>set("backPainNrs",v)} min={0} max={10}/></div>{showClaudication&&<details open className="conditional"><summary>Walking and claudication details</summary><div className="grid three"><StatusField label="Provoked by standing?" value={data.standingProvokes} onChange={v=>set("standingProvokes",v)}/><StatusField label="Provoked by walking?" value={data.walkingProvokes} onChange={v=>set("walkingProvokes",v)}/><StatusField label="Relieved by sitting?" value={data.sittingRelieves} onChange={v=>set("sittingRelieves",v)}/><StatusField label="Relieved by flexion?" value={data.flexionRelieves} onChange={v=>set("flexionRelieves",v)}/><StatusField label="Bicycle better than walking?" value={data.bicycleBetter} onChange={v=>set("bicycleBetter",v)}/><StatusField label="Leg heaviness?" value={data.legHeaviness} onChange={v=>set("legHeaviness",v)}/><MeasurementField label="Walking limit" m={data.walkingLimitMeters} onChange={v=>set("walkingLimitMeters",v)} min={0} max={50000}/><StatusField label="Lower-extremity pulses abnormal?" value={data.pulsesAbnormal} onChange={v=>set("pulsesAbnormal",v)}/><StatusField label="Relieved by standing still alone, without flexion?" value={data.stoppingAloneRelieves} onChange={v=>set("stoppingAloneRelieves",v)} hint="Favours vascular over neurogenic claudication."/><StatusField label="Uphill easier than downhill walking?" value={data.uphillBetterThanDownhill} onChange={v=>set("uphillBetterThanDownhill",v)} hint="Flexion-favouring pattern."/></div></details>}</Card>{workflowMode==="comprehensive"&&<Card title="Patient-reported function" className="outcomes-card"><p className="section-intro">Optional baseline outcomes document disability and function. They inform longitudinal follow-up but do not determine localization or treatment.</p><div className="grid three"><MeasurementField label="ODI" m={data.baselineOdi} onChange={v=>set("baselineOdi",v)} min={0} max={100} hint="Oswestry Disability Index, 0–100; higher scores indicate greater disability."/><MeasurementField label="PROMIS Physical Function" m={data.baselinePromisPf} onChange={v=>set("baselinePromisPf",v)} min={0} max={100} step={0.1} hint="T-score; higher scores indicate better physical function."/><MeasurementField label="PROMIS Pain Interference" m={data.baselinePromisPi} onChange={v=>set("baselinePromisPi",v)} min={0} max={100} step={0.1} hint="T-score; higher scores indicate greater pain interference."/></div><div className="context-note"><b>Use consistently</b><span>Collect the same instrument at follow-up. Do not apply a single universal MCID across diagnoses, instruments, and time points.</span></div></Card>}<Card title="Focused neurologic examination" action={<button className="link-button" onClick={()=>setAdvancedExam(x=>!x)}>{advancedExam?"Hide advanced":"Show advanced"}</button>}><div className="motor-table"><b>Motor function</b><b>Right</b><b>Left</b>{[["Knee extension","rightKneeExtension","leftKneeExtension"],["Ankle dorsiflexion","rightAnkleDorsiflexion","leftAnkleDorsiflexion"],["Great-toe extension","rightGreatToeExtension","leftGreatToeExtension"],["Plantar flexion","rightPlantarFlexion","leftPlantarFlexion"]].map(([n,r,l])=><FragmentRow key={n} label={n} right={data[r as keyof CaseInput] as MotorGrade} left={data[l as keyof CaseInput] as MotorGrade} onRight={v=>set(r as keyof CaseInput,v as never)} onLeft={v=>set(l as keyof CaseInput,v as never)}/>)}</div><div className="grid three"><Field label="Exam reliability"><Select value={data.examConfidence} options={["not-assessed","low","moderate","high"] as const} onChange={v=>set("examConfidence",v)}/></Field><Field label="Weakness quality"><Select value={data.weaknessQuality} options={["not-assessed","true","pain-limited","give-way","uncertain"] as const} onChange={v=>set("weaknessQuality",v)}/></Field><Field label="Trajectory"><Select value={data.weaknessTrajectory} options={["not-assessed","none","stable","improving","progressive"] as const} onChange={v=>set("weaknessTrajectory",v)}/></Field><StatusField label="Heel walking abnormal?" value={data.heelWalkAbnormal} onChange={v=>set("heelWalkAbnormal",v)}/><StatusField label="Toe walking abnormal?" value={data.toeWalkAbnormal} onChange={v=>set("toeWalkAbnormal",v)}/><Field label="Straight-leg raise"><Select value={data.straightLegRaise} options={["not-tested","negative","positive"] as const} onChange={v=>set("straightLegRaise",v)}/></Field></div>{advancedExam&&<div className="advanced-panel"><div className="grid three"><Field label="Right sensory root"><Select value={data.rightSensoryRoot} options={["not-tested","none","L4","L5","S1","multiroot","non-dermatomal","not-assessed"] as const} onChange={v=>set("rightSensoryRoot",v)}/></Field><Field label="Left sensory root"><Select value={data.leftSensoryRoot} options={["not-tested","none","L4","L5","S1","multiroot","non-dermatomal","not-assessed"] as const} onChange={v=>set("leftSensoryRoot",v)}/></Field><Field label="Femoral stretch"><Select value={data.femoralStretch} options={["not-tested","negative","positive"] as const} onChange={v=>set("femoralStretch",v)}/></Field><Field label="Right patellar reflex"><Select value={data.rightPatellarReflex} options={reflexes} onChange={v=>set("rightPatellarReflex",v)}/></Field><Field label="Left patellar reflex"><Select value={data.leftPatellarReflex} options={reflexes} onChange={v=>set("leftPatellarReflex",v)}/></Field><Field label="Right Achilles reflex"><Select value={data.rightAchillesReflex} options={reflexes} onChange={v=>set("rightAchillesReflex",v)}/></Field><Field label="Left Achilles reflex"><Select value={data.leftAchillesReflex} options={reflexes} onChange={v=>set("leftAchillesReflex",v)}/></Field><StatusField label="Hip examination abnormal?" value={data.hipExamAbnormal} onChange={v=>set("hipExamAbnormal",v)}/><StatusField label="Groin pain?" value={data.groinPain} onChange={v=>set("groinPain",v)} hint="Raises a competing hip explanation."/><StatusField label="Peripheral neuropathy features?" value={data.neuropathyFeatures} onChange={v=>set("neuropathyFeatures",v)}/><StatusField label="Muscle atrophy?" value={data.muscleAtrophy} onChange={v=>set("muscleAtrophy",v)}/><StatusField label="Repeated single-leg heel raise abnormal?" value={data.repeatedHeelRaiseAbnormal} onChange={v=>set("repeatedHeelRaiseAbnormal",v)}/></div></div>}</Card></>)}

   {step===3&&(workflowMode==="rapid"?<><Card title="Rapid imaging confirmation"><p className="section-intro">Document one potentially relevant compressive finding. Use Comprehensive review for multilevel, postoperative, deformity, or fusion planning.</p><div className="grid three"><Field label="Source"><select value={data.imagesReviewed} onChange={e=>set("imagesReviewed",e.target.value as ClinicalStatus)}><option value="not-assessed">Not assessed</option><option value="present">Images directly reviewed</option><option value="absent">Report reviewed only</option><option value="unknown">Source unknown</option></select></Field><StatusField label="Potentially relevant compressive finding?" value={rapidImagingStatus} onChange={setRapidImagingFinding}/>{data.imagesReviewed==="present"&&<Field label="Image quality"><Select value={data.imageQuality} options={["not-assessed","adequate","limited","unknown"] as const} onChange={v=>set("imageQuality",v)}/></Field>}</div>{rapidImagingStatus==="present"&&<div className="grid three rapid-branch"><Field label="Level"><Select value={rapidImagingLevel} options={["not-assessed",...levels] as const} onChange={v=>applyRapidImaging(v,rapidImagingZone,rapidImagingSeverity)}/></Field><Field label="Zone"><Select value={rapidImagingZone} options={["not-assessed","central","right-recess","left-recess","right-foramen","left-foramen"] as const} onChange={v=>applyRapidImaging(rapidImagingLevel,v,rapidImagingSeverity)}/></Field><Field label="Severity"><Select value={rapidImagingSeverity} options={["not-graded","mild","moderate","severe"] as const} onChange={v=>applyRapidImaging(rapidImagingLevel,rapidImagingZone,v)}/></Field></div>}</Card></>:<><Card title="Imaging source"><div className="grid three"><Field label="Imaging source"><select value={data.imagesReviewed} onChange={e=>set("imagesReviewed",e.target.value as ClinicalStatus)}><option value="not-assessed">Not assessed</option><option value="present">Images directly reviewed</option><option value="absent">Report reviewed only / no direct image review</option><option value="unknown">Source unknown</option></select><small className="field-note">Direct review and report-only abstraction are retained as different evidence sources.</small></Field><Field label="Image quality"><Select value={data.imageQuality} options={["not-assessed","unknown","limited","adequate"] as const} onChange={v=>set("imageQuality",v)}/></Field><MeasurementField label="Imaging age" m={data.imagingAgeMonths} onChange={v=>set("imagingAgeMonths",v)} min={0} max={600}/></div></Card><Card title="Potentially relevant levels"><p className="muted">Select only levels that may explain the current presentation. Full normal-level documentation remains available in research mode.</p><div className="level-picker">{levels.map(l=><button key={l} className={activeLevels.includes(l)?"selected":""} onClick={()=>toggleLevel(l)}>{l}</button>)}</div>{activeLevels.length===0&&<p className="empty-state">No level selected.</p>}{activeLevels.map(level=>{const f=data.imagingMatrix.find(x=>x.level===level)!;return <article className="level-card" key={level}><h3>{level}</h3><div className="grid three"><Field label="Central canal"><Select value={f.central} options={severities} onChange={v=>updateLevel(level,"central",v)}/></Field><Field label="Right lateral recess"><Select value={f.rightRecess} options={severities} onChange={v=>updateLevel(level,"rightRecess",v)}/></Field><Field label="Left lateral recess"><Select value={f.leftRecess} options={severities} onChange={v=>updateLevel(level,"leftRecess",v)}/></Field><Field label="Right foramen"><Select value={f.rightForamen} options={severities} onChange={v=>updateLevel(level,"rightForamen",v)}/></Field><Field label="Left foramen"><Select value={f.leftForamen} options={severities} onChange={v=>updateLevel(level,"leftForamen",v)}/></Field><StatusField label="Root deformation?" value={f.rootDeformation} onChange={v=>updateLevel(level,"rootDeformation",v)}/></div><details><summary>Advanced imaging details</summary><div className="grid three"><Field label="Disc morphology"><Select value={f.discMorphology} options={["not-assessed","none","bulge","protrusion","extrusion","sequestration"] as const} onChange={v=>updateLevel(level,"discMorphology",v)}/></Field><Field label="Migration"><Select value={f.migration} options={["not-assessed","none","cranial","caudal"] as const} onChange={v=>updateLevel(level,"migration",v)}/></Field><StatusField label="Prior decompression at this level?" value={f.priorDecompression} onChange={v=>updateLevel(level,"priorDecompression",v)}/></div></details></article>})}</Card></>)}

   {step===4&&(workflowMode==="rapid"?<><Card title="Rapid treatment context"><div className="grid four"><StatusField label="Structured exercise or PT attempted?" value={data.exerciseProgramCompleted} onChange={v=>set("exerciseProgramCompleted",v)}/><StatusField label="Medication trial attempted?" value={data.medicationTrialCompleted} onChange={v=>set("medicationTrialCompleted",v)}/><Field label="Most relevant injection response"><select value={data.injectionResponse} onChange={e=>set("injectionResponse",e.target.value as CaseInput["injectionResponse"])}>{(["unknown","not-tried","none","brief","meaningful-temporary","sustained"] as const).map(x=><option key={x} value={x}>{injectionResponseLabel(x)}</option>)}</select></Field><Field label="Clinical pathway being considered"><Select value={data.proposedProcedure} options={["not-assessed","none","decompression","discectomy","fusion","decompression-fusion","other"] as const} onChange={v=>set("proposedProcedure",v)}/></Field></div>{showInjectionTarget&&<div className="grid two rapid-branch"><Field label="Injection level"><Select value={data.injectionLevel} options={["unknown",...levels] as const} onChange={v=>set("injectionLevel",v)}/></Field><Field label="Injection side"><Select value={data.injectionSide} options={["not-assessed","right","left","bilateral","midline"] as const} onChange={v=>set("injectionSide",v)}/></Field></div>}{showFusion&&<div className="mode-escalation"><b>Fusion assessment requires Comprehensive review</b><span>Switch modes to document level-specific instability, revision, deformity, bone health, and optimization factors.</span><button type="button" onClick={()=>switchMode("comprehensive")}>Open Comprehensive review</button></div>}</Card></>:<><Card title="Prior nonoperative treatment" className="treatment-card"><div className="grid three"><StatusField label="Structured exercise or physical therapy completed?" value={data.exerciseProgramCompleted} onChange={v=>set("exerciseProgramCompleted",v)}/>{data.exerciseProgramCompleted==="present"&&<MeasurementField label="Exercise or therapy duration" m={data.exerciseWeeks} onChange={v=>set("exerciseWeeks",v)} min={0} max={520} hint="Enter the approximate completed duration."/>}<StatusField label="Medication trial completed?" value={data.medicationTrialCompleted} onChange={v=>set("medicationTrialCompleted",v)}/><Field label="Response to the most relevant lumbar injection" fieldId="injectionResponse" hint="Record the response only when the injection target is known or explicitly undocumented."><select value={data.injectionResponse} onChange={e=>{const v=e.target.value as CaseInput["injectionResponse"];set("injectionResponse",v);if(v==="not-tried"||v==="unknown"){set("injectionLevel",v==="not-tried"?"not-applicable":"unknown");set("injectionSide","not-assessed")}}}>{(["unknown","not-tried","none","brief","meaningful-temporary","sustained"] as const).map(v=><option key={v} value={v}>{injectionResponseLabel(v)}</option>)}</select></Field>{showInjectionTarget&&<><Field label="Injection level" fieldId="injectionLevel" required="Required when a response is recorded"><Select value={data.injectionLevel} options={["unknown",...levels] as const} onChange={v=>set("injectionLevel",v)}/></Field><Field label="Injection side" fieldId="injectionSide" required="Required when a response is recorded"><Select value={data.injectionSide} options={["not-assessed","right","left","bilateral","midline"] as const} onChange={v=>set("injectionSide",v)}/></Field></>}</div>{showInjectionTarget&&<div className="context-note"><b>Interpretation boundary</b><span>An injection response is supportive context only. It does not independently establish the symptomatic level or determine treatment.</span></div>}</Card><Card title="Proposed clinical pathway"><div className="grid three"><Field label="Clinical pathway being considered"><Select value={data.proposedProcedure} options={["not-assessed","none","decompression","discectomy","fusion","decompression-fusion","other"] as const} onChange={v=>set("proposedProcedure",v)}/></Field>{data.proposedProcedure!=="not-assessed"&&data.proposedProcedure!=="none"&&<Field label="Level(s) being considered" fieldId="proposedLevels"><div className="level-checks">{levels.map(l=><label key={l}><input type="checkbox" checked={data.proposedLevels.includes(l)} onChange={()=>set("proposedLevels",data.proposedLevels.includes(l)?data.proposedLevels.filter(x=>x!==l):[...data.proposedLevels,l])}/>{l}</label>)}</div></Field>}<Field label="Planned setting"><Select value={data.plannedSetting} options={["not-assessed","outpatient","inpatient"] as const} onChange={v=>set("plannedSetting",v)}/></Field></div></Card>{showFusion&&<Card title="Level-specific fusion rationale"><p className="muted">Only proposed levels are shown. A fusion finding at another level cannot justify fusion at the target level.</p>{data.proposedLevels.map(level=>{const f=data.fusionMatrix.find(x=>x.level===level)!;return <article className="level-card" key={level}><h3>{level}</h3><div className="grid three"><StatusField label="Dynamic instability?" value={f.dynamicInstability} onChange={v=>updateFusion(level,"dynamicInstability",v)}/>{f.dynamicInstability==="present"&&<><MeasurementField label="Translation" m={f.translationMm} onChange={v=>updateFusion(level,"translationMm",v)} min={0} max={20}/><MeasurementField label="Angular motion" m={f.angularMotionDeg} onChange={v=>updateFusion(level,"angularMotionDeg",v)} min={0} max={40}/></>}<StatusField label="Foraminal height loss or exiting-root compression?" value={f.foraminalCollapse} onChange={v=>updateFusion(level,"foraminalCollapse",v)}/><MeasurementField label="Planned facet resection" m={f.plannedFacetResectionPercent} onChange={v=>updateFusion(level,"plannedFacetResectionPercent",v)} min={0} max={100}/><StatusField label="Revision-related destabilization?" value={f.revisionDestabilization} onChange={v=>updateFusion(level,"revisionDestabilization",v)}/><StatusField label="Pseudarthrosis?" value={f.pseudarthrosis} onChange={v=>updateFusion(level,"pseudarthrosis",v)}/><StatusField label="Relevant deformity at this level?" value={f.relevantDeformity} onChange={v=>updateFusion(level,"relevantDeformity",v)}/></div></article>})}</Card>}<Card title="Core optimization screen" action={<button className="link-button" onClick={()=>setAdvancedRisk(x=>!x)}>{advancedRisk?"Hide additional":"Additional medical details"}</button>}><div className="grid three"><Field label="Smoking status"><Select value={data.smokingStatus} options={["not-assessed","never","former","current"] as const} onChange={v=>set("smokingStatus",v)}/></Field><Field label="Diabetes"><Select value={data.diabetesType} options={["not-assessed","none","type-1","type-2","other"] as const} onChange={v=>set("diabetesType",v)}/></Field>{data.diabetesType!=="none"&&data.diabetesType!=="not-assessed"&&<MeasurementField label="HbA1c" m={data.hba1c} onChange={v=>set("hba1c",v)} min={3} max={20} step={0.1}/>}<Field label="Prior lumbar surgery"><Select value={data.priorSurgeryType} options={["not-assessed","none","decompression","discectomy","fusion","multiple"] as const} onChange={v=>set("priorSurgeryType",v)}/></Field><Field label="Bone health"><Select value={data.boneHealth} options={["not-assessed","unknown","normal","osteopenia","osteoporosis"] as const} onChange={v=>set("boneHealth",v)}/></Field><StatusField label="Chronic opioid exposure?" value={data.chronicOpioidUse} onChange={v=>set("chronicOpioidUse",v)}/><StatusField label="Major cardiopulmonary disease?" value={data.cardiopulmonaryDisease} onChange={v=>set("cardiopulmonaryDisease",v)}/><StatusField label="Anticoagulation?" value={data.anticoagulation} onChange={v=>set("anticoagulation",v)}/></div>{advancedRisk&&<div className="advanced-panel"><div className="grid three"><MeasurementField label="BMI" m={data.bmi} onChange={v=>set("bmi",v)} min={10} max={80} step={0.1}/><MeasurementField label="Hemoglobin" m={data.hemoglobin} onChange={v=>set("hemoglobin",v)} min={3} max={22} step={0.1}/><MeasurementField label="Albumin" m={data.albumin} onChange={v=>set("albumin",v)} min={1} max={6} step={0.1}/><MeasurementField label="Clinical Frailty Scale" m={data.frailtyScale} onChange={v=>set("frailtyScale",v)} min={1} max={9}/><MeasurementField label="DEXA T-score" m={data.dexTScore} onChange={v=>set("dexTScore",v)} min={-7} max={5} step={0.1}/><MeasurementField label="Opioid MME/day" m={data.opioidMme} onChange={v=>set("opioidMme",v)} min={0} max={2000}/><StatusField label="Prior DVT/PE?" value={data.priorDvtPe} onChange={v=>set("priorDvtPe",v)}/><StatusField label="Sleep apnea?" value={data.sleepApnea} onChange={v=>set("sleepApnea",v)}/>{data.sleepApnea==="present"&&<StatusField label="CPAP adherent?" value={data.cpapAdherent} onChange={v=>set("cpapAdherent",v)}/>}<StatusField label="Advanced renal or liver disease?" value={data.advancedRenalOrLiverDisease} onChange={v=>set("advancedRenalOrLiverDisease",v)}/><StatusField label="Nicotine vaping?" value={data.nicotineVaping} onChange={v=>set("nicotineVaping",v)}/><StatusField label="Smokeless tobacco?" value={data.smokelessTobacco} onChange={v=>set("smokelessTobacco",v)}/><StatusField label="Prior fragility fracture?" value={data.fragilityFracture} onChange={v=>set("fragilityFracture",v)}/></div>{data.priorSurgeryType!=="none"&&data.priorSurgeryType!=="not-assessed"&&<div className="grid three" style={{marginTop:14}}><StatusField label="Revision at the same level?" value={data.sameLevelRevision} onChange={v=>set("sameLevelRevision",v)}/><StatusField label="Prior dural tear?" value={data.priorDuralTear} onChange={v=>set("priorDuralTear",v)}/><StatusField label="Prior surgical-site infection?" value={data.priorInfection} onChange={v=>set("priorInfection",v)}/><StatusField label="Prior pseudarthrosis?" value={data.priorPseudarthrosis} onChange={v=>set("priorPseudarthrosis",v)}/></div>}</div>}</Card></>)}

   {step===5&&<><Card title={workflowMode==="rapid"?"Physician attention check":"Data-quality review"}><div className="review-summary"><div className="review-stat error"><b>{errors.length}</b><span>Blocking errors</span></div><div className="review-stat warning"><b>{warnings.length}</b><span>Important warnings</span></div><div className="review-stat info"><b>{infos.length}</b><span>Advisories</span></div></div><IssuePanel issues={issues} onJump={jump}/></Card>{warnings.length>0&&!errors.length&&<label className="acknowledge"><input type="checkbox" checked={warningsAcknowledged} onChange={e=>setWarningsAcknowledged(e.target.checked)}/>I reviewed the warnings and confirm that the unusual or discordant entries are intentional or clinically unresolved.</label>}<div className="generate-panel"><h3>{errors.length?"Resolve blocking errors before synthesis":workflowMode==="rapid"?"Generate preliminary synthesis":"Generate clinical synthesis"}</h3><p>{workflowMode==="rapid"?"Rapid review provides a preliminary safety, syndrome, discordance, and candidate-localization summary. Switch to Comprehensive review for multilevel, fusion, optimization, outcomes, or research-ready documentation.":"The report prioritizes urgency, syndrome, concordant target, uncertainty, next step, and documented fusion-rationale factors. Detailed reasoning remains available but collapsed."}</p><button className="primary" disabled={errors.length>0} onClick={generate}>{warnings.length&&!warningsAcknowledged?"Review warnings first":"Generate synthesis"}</button></div></>}

   <div className="step-actions"><button disabled={step===0} onClick={()=>setStep(s=>outOfScope&&s===5?1:s-1)}>Previous</button>{step<steps.length-1&&<button className="primary" onClick={()=>setStep(s=>outOfScope&&s===1?5:s+1)}>Continue</button>}</div>
  </section></div>}

  {view==="results"&&result&&<section className="results-page"><div className="results-head"><div><small>{generatedWorkflowMode==="rapid"?"Preliminary rapid synthesis":"Clinical synthesis"} · ruleset {RULESET_VERSION}</small><p className="snapshot-label">Generated from assessment snapshot at {generatedAt?new Date(generatedAt).toLocaleString():"unknown time"}</p><h2>{generatedWorkflowMode==="rapid"?"Rapid lumbar review":"Lumbar clinical–imaging synthesis"}</h2><p>Clinician confirmation is required. The framework organizes concordance and uncertainty; it does not make an autonomous diagnosis or treatment decision.</p></div><div className="result-actions"><button onClick={()=>setView("entry")}>Edit inputs</button><button onClick={copySummary}>{copyState==="copied"?"Copied":copyState==="failed"?"Copy failed":"Copy handoff"}</button><button onClick={printSummary}>Print / save PDF</button></div></div>{snapshot&&[snapshot.baselineOdi,snapshot.baselinePromisPf,snapshot.baselinePromisPi].some(m=>m.status==="measured")&&<div className="outcome-strip"><div><span>ODI</span><b>{snapshot.baselineOdi.status==="measured"?snapshot.baselineOdi.value:"—"}</b></div><div><span>PROMIS PF</span><b>{snapshot.baselinePromisPf.status==="measured"?snapshot.baselinePromisPf.value:"—"}</b></div><div><span>PROMIS PI</span><b>{snapshot.baselinePromisPi.status==="measured"?snapshot.baselinePromisPi.value:"—"}</b></div><p>Baseline context only; these scores do not establish a symptomatic level or treatment indication.</p></div>}<div className="executive-grid">{result.highlights.map(h=><article key={h.ruleId} className={`highlight tone-border-${h.tone}`}><ToneBadge tone={h.tone}>{h.title}</ToneBadge><p>{h.detail}</p></article>)}</div><Card title="Standardized physician handoff" className="handoff-card"><div className="handoff-grid"><div><small>Clinical problem</small><b>{label(result.syndrome.derived)}</b></div><div><small>Localization</small><b>{result.targets[0]?`${label(result.targets[0].side)} ${result.targets[0].root} · ${label(result.targets[0].level)} ${label(result.targets[0].zone)}`:"Not established"}</b></div><div><small>Immediate priority</small><b>{label(result.urgency)}</b></div><div><small>Recommended action</small><b>{result.nextSteps[0]??result.specialistReview.reasons[0]??"Clinical review required"}</b></div></div></Card>{(()=>{const alerts=buildPriorityAlerts(result,generatedIssues,generatedWorkflowMode);return alerts.length>0?<Card title="Do not miss" className="donotmiss-card"><div className="alert-stack">{alerts.map(a=><div key={a.id} className={`priority-alert tier-${a.tier}`}><span className="alert-tier">{a.tier==="blocking"?"Blocking":a.tier==="important"?"Important":"Advisory"}</span><div className="alert-body"><b>{a.title}</b><small>{a.detail}</small></div><button type="button" className="alert-action" onClick={()=>{if(a.action==="Switch to Comprehensive"){switchMode("comprehensive");setView("entry")}else{setView("entry");if(a.domain!==undefined)setStep(domainStep[a.domain]);if(a.field)setTimeout(()=>document.querySelector(`[data-field="${a.field}"]`)?.scrollIntoView({behavior:"smooth",block:"center"}),50)}}}>{a.action}</button></div>)}</div></Card>:null})()}<Card title="Concordance map"><div className="concordance-table"><div className="concordance-head"><b>Domain</b><b>Recorded finding</b><b>Interpretation</b></div>{result.concordance.map(row=><div className="concordance-row" key={row.domain}><b>{row.domain}</b><span>{row.finding}</span><span className={`concordance-status ${row.status}`}>{row.status==="support"?"Concordant":row.status==="conflict"?"Conflict":row.status==="missing"?"Missing":"Context"}</span></div>)}</div></Card><div className={`two-col-results ${result.missing.length||result.mimics.length?"":"single-result"}`}><Card title="Most concordant candidate localization">{result.targets[0]?<><h3>{label(result.targets[0].side)} {result.targets[0].root} · {result.targets[0].level} {label(result.targets[0].zone)}</h3><div className="evidence-columns"><div><b>Supports</b><List items={result.targets[0].support} emptyText="No supporting domain recorded."/></div><div><b>Conflicts</b><List items={result.targets[0].conflicts} emptyText="No direct conflict identified."/></div><div><b>Unavailable</b><List items={result.targets[0].unavailable} emptyText="No key domain unavailable."/></div></div></>:<p className="empty-state">Current information does not establish a concordant candidate localization. Additional localization is needed before procedure-specific review. Review the concordance map and unresolved items below.</p>}</Card>{(result.missing.length>0||result.mimics.length>0)&&<Card title="Information requiring resolution">{result.missing.length>0&&<div className="result-subsection"><b>Missing or contradictory information</b><List items={result.missing}/></div>}{result.mimics.length>0&&<div className="result-subsection"><b>Competing explanations</b><List items={result.mimics}/></div>}</Card>}</div>{result.scopeNotes.length>0&&<Card title="Scope and screen limitations" className="scope-card"><p className="section-intro">These are results and boundaries of what was reviewed, not unresolved data errors.</p><List items={result.scopeNotes}/></Card>}<Card title="Prioritized next steps" className="next-step-card"><List items={result.nextSteps}/><List items={result.nonoperative}/></Card><details className="result-details"><summary>Detailed clinical reasoning</summary><div className="three-col-results"><Card title="Syndrome"><p className="lead">{label(result.syndrome.derived)}</p><List items={result.syndrome.rationale}/><List items={result.syndrome.conflicts}/></Card><Card title="Neurologic assessment"><p className="lead">{label(result.neurologic.severity)} · {label(result.neurologic.reliability)} reliability</p><List items={result.neurologic.rationale}/></Card><Card title="Specialist review"><p className="lead">{label(result.specialistReview.status)}</p><List items={result.specialistReview.reasons}/><List items={result.specialistReview.limitations}/></Card>{result.fusion.status!=="not-applicable"&&<Card title="Fusion-rationale factors"><p className="lead">{label(result.fusion.status)}</p>{result.fusion.level&&<p><b>Level:</b> {result.fusion.level}</p>}<List items={result.fusion.reasons}/><List items={result.fusion.missing}/></Card>}{(result.risk.patientSpecific.length>0||result.risk.procedureSpecific.length>0)&&<Card title="Perioperative considerations"><List items={result.risk.patientSpecific}/><List items={result.risk.procedureSpecific}/></Card>}</div></details><details className="result-details"><summary>Evidence relevant to this case</summary><p className="muted">Only evidence linked to conclusions triggered by this case is shown. Technical rule identifiers remain in the research workspace.</p><div className="rule-table clinician-evidence">{result.ruleTrace.map(r=>{const items=getEvidenceList(r.evidenceIds);return <article key={r.ruleId}><div><b>{r.conclusion}</b><span>{label(r.strength)}</span></div>{items.length?<div className="evidence-items">{items.map(e=><div key={e.id} className="evidence-item"><b>{e.citation}</b><span className="evidence-type">{label(e.studyType)}</span><p>{e.mainFinding}</p><small><b>Population:</b> {e.population}</small><small><b>Applicability to this rule:</b> {e.applicability}</small><small><b>Key exclusions:</b> {e.keyExclusions}</small><small><b>Limitations:</b> {e.limitations}</small><a href={e.url} target="_blank" rel="noreferrer">Open source</a></div>)}</div>:<small className="no-evidence">No disease-specific clinical evidence is cited for this conclusion. It rests on documentation completeness and expert consensus rather than on outcome data.</small>}</article>})}</div></details></section>}


  {view==="literature"&&<section className="results-page"><div className="results-head"><div><small>Expanded curated evidence library · reviewed 2026-08-03</small><h2>Evidence supporting the framework</h2><p>High-quality guidelines, randomized trials, systematic reviews, and outcome-measure studies relevant to the lumbar module. This is an expanded curated registry, not a claim of exhaustive coverage.</p></div></div><div className="evidence-notice"><b>Two evidence views</b><span>This page summarizes the broader reviewed library. The synthesis shows only sources linked to conclusions triggered by the current case.</span></div><div className="literature-grid">
<article className="literature-card"><div className="literature-meta"><span>Guideline</span><span>Radiculopathy</span></div><h3>Lumbar disc herniation with radiculopathy</h3><p>History, neurologic examination, and imaging should be interpreted together. Imaging alone does not establish the symptomatic side, root, or level.</p><a href="https://pubmed.ncbi.nlm.nih.gov/24239490/" target="_blank" rel="noreferrer">Open NASS guideline summary</a></article>
<article className="literature-card"><div className="literature-meta"><span>Guideline</span><span>Low back pain and sciatica</span></div><h3>Assessment and nonoperative care</h3><p>Assessment should address serious pathology, neurologic deterioration, function, symptom duration, prior care, and patient preferences.</p><a href="https://www.nice.org.uk/guidance/ng59" target="_blank" rel="noreferrer">Open NICE guidance</a></article>
<article className="literature-card"><div className="literature-meta"><span>Imaging guideline</span><span>Low back pain</span></div><h3>Appropriate imaging use</h3><p>Imaging selection depends on red flags, neurologic deficit, symptom persistence, prior surgery, and the specific clinical scenario.</p><a href="https://www.acr.org/clinical-resources/clinical-tools-and-reference/appropriateness-criteria" target="_blank" rel="noreferrer">Open ACR Appropriateness Criteria</a></article>
<article className="literature-card"><div className="literature-meta"><span>Systematic review</span><span>Imaging interpretation</span></div><h3>Degenerative findings in asymptomatic adults</h3><p>Degenerative MRI and CT findings are common in people without pain and increase with age. Imaging findings require clinical correlation.</p><a href="https://pubmed.ncbi.nlm.nih.gov/25430861/" target="_blank" rel="noreferrer">Open systematic review</a></article>
<article className="literature-card"><div className="literature-meta"><span>Systematic review</span><span>Examination</span></div><h3>Straight-leg raise diagnostic utility</h3><p>The straight-leg raise can contribute to radicular assessment, but its diagnostic performance varies and it should not be interpreted in isolation.</p><a href="https://pubmed.ncbi.nlm.nih.gov/23220802/" target="_blank" rel="noreferrer">Open systematic review</a></article>
<article className="literature-card"><div className="literature-meta"><span>Prospective trial</span><span>8-year follow-up</span></div><h3>SPORT: lumbar disc herniation</h3><p>Carefully selected surgical candidates with imaging-confirmed disc herniation improved with both operative and nonoperative care; as-treated analyses favored surgery, while crossover complicated randomized comparisons.</p><a href="https://pubmed.ncbi.nlm.nih.gov/24153171/" target="_blank" rel="noreferrer">Open SPORT report</a></article>
<article className="literature-card"><div className="literature-meta"><span>Prospective trial</span><span>8-year follow-up</span></div><h3>SPORT: lumbar spinal stenosis</h3><p>Long-term results differed by analytic approach and substantial treatment crossover. Findings apply to symptomatic surgical candidates with confirmatory imaging.</p><a href="https://pubmed.ncbi.nlm.nih.gov/25569524/" target="_blank" rel="noreferrer">Open SPORT stenosis report</a></article>
<article className="literature-card"><div className="literature-meta"><span>Randomized trial</span><span>5-year follow-up</span></div><h3>NORDSTEN-DS: decompression alone versus fusion</h3><p>In selected patients with stenosis and degenerative spondylolisthesis, decompression alone was non-inferior to decompression with fusion at five years. Important exclusions limit generalization.</p><a href="https://www.bmj.com/content/386/bmj-2024-079771" target="_blank" rel="noreferrer">Open NORDSTEN-DS</a></article>
<article className="literature-card"><div className="literature-meta"><span>Randomized trial</span><span>5-year follow-up</span></div><h3>Swedish Spinal Stenosis Study</h3><p>In one- or two-level central stenosis, five-year outcomes did not support routine addition of fusion; applicability remains population-specific.</p><a href="https://pubmed.ncbi.nlm.nih.gov/38945544/" target="_blank" rel="noreferrer">Open trial abstract</a></article>
<article className="literature-card"><div className="literature-meta"><span>Imaging study</span><span>Foraminal stenosis</span></div><h3>Standardized foraminal grading</h3><p>The Lee MRI grading system showed high reader agreement. Grading supports structured documentation but does not by itself establish the symptomatic root.</p><a href="https://pubmed.ncbi.nlm.nih.gov/20308517/" target="_blank" rel="noreferrer">Open grading study</a></article>
<article className="literature-card"><div className="literature-meta"><span>Systematic review</span><span>Foraminal stenosis</span></div><h3>Clinical correlation remains imperfect</h3><p>Published grading systems are heterogeneous, and symptom correlation is mixed. Foraminal severity should be reconciled with side, root, examination, and function.</p><a href="https://pubmed.ncbi.nlm.nih.gov/41695907/" target="_blank" rel="noreferrer">Open systematic review</a></article>
<article className="literature-card"><div className="literature-meta"><span>Systematic review</span><span>Fusion risk</span></div><h3>Pseudarthrosis risk factors</h3><p>Age, smoking, and the number of fused levels were associated with lumbar pseudarthrosis in pooled analyses. These findings inform optimization and risk discussion, not automatic treatment selection.</p><a href="https://pubmed.ncbi.nlm.nih.gov/38831392/" target="_blank" rel="noreferrer">Open meta-analysis</a></article>
<article className="literature-card"><div className="literature-meta"><span>Systematic review</span><span>Frailty</span></div><h3>Frailty and degenerative spine surgery</h3><p>Frailty is associated with higher complication, mortality, non-home discharge, and length-of-stay risk after degenerative spine surgery. It is a perioperative risk domain rather than a localization rule.</p><a href="https://pubmed.ncbi.nlm.nih.gov/37996826/" target="_blank" rel="noreferrer">Open meta-analysis</a></article>
<article className="literature-card"><div className="literature-meta"><span>Outcome measure</span><span>ODI</span></div><h3>Oswestry Disability Index</h3><p>ODI is a widely used low-back-pain disability measure with established validity, reliability, and responsiveness. It measures disability, not anatomic localization.</p><a href="https://pubmed.ncbi.nlm.nih.gov/19646379/" target="_blank" rel="noreferrer">Open psychometric review</a></article>
<article className="literature-card"><div className="literature-meta"><span>Outcome measure</span><span>PROMIS</span></div><h3>PROMIS Physical Function and Pain Interference</h3><p>PROMIS domains provide standardized T-scores and have demonstrated validity in lumbar populations. Scores are longitudinal outcomes, not treatment-selection rules.</p><a href="https://pubmed.ncbi.nlm.nih.gov/26970039/" target="_blank" rel="noreferrer">Open PROMIS validity study</a></article>
<article className="literature-card"><div className="literature-meta"><span>Reporting standard</span><span>Validation</span></div><h3>TRIPOD+AI</h3><p>Any future predictive component requires prespecified outcomes, transparent methods, calibration, external validation, and subgroup evaluation.</p><a href="https://pubmed.ncbi.nlm.nih.gov/38626948/" target="_blank" rel="noreferrer">Open TRIPOD+AI</a></article>
<article className="literature-card"><div className="literature-meta"><span>Clinical evaluation</span><span>Human factors</span></div><h3>DECIDE-AI</h3><p>Prospective pilot evaluation should assess safety, workflow fit, clinician interaction, and real-world performance before broader deployment.</p><a href="https://pubmed.ncbi.nlm.nih.gov/35584845/" target="_blank" rel="noreferrer">Open DECIDE-AI</a></article>
</div><details className="result-details"><summary>Evidence governance</summary><div className="three-col-results"><Card title="Selection"><List items={["Prioritize current guidelines, randomized trials, systematic reviews, diagnostic-accuracy studies, and strong prospective cohorts","Match population, clinical question, intervention, and outcome to the rule being supported","Record full citation, study design, population, exclusions, applicability, limitations, and review date"]}/></Card><Card title="Boundaries"><List items={["A study result is not automatically a treatment rule","PROMs measure symptoms and function; they do not localize a symptomatic level","Conflicting evidence and excluded populations remain visible","Evidence strength applies to the source and question, not to an individual patient conclusion"]}/></Card><Card title="Maintenance"><List items={["Review the registry on a defined schedule","Require multidisciplinary adjudication before evidence changes alter a clinical rule","Archive superseded sources for reproducibility","Label this library as curated until a formal systematic review is completed"]}/></Card></div></details></section>}

  {view==="research"&&<section className="results-page"><div className="results-head"><div><small>Research workspace — prototype</small><h2>Validation and adjudication</h2><p>Independent judgments, app output, actual care, and outcomes remain separate.</p></div>{snapshot&&result&&<button onClick={exportJson}>Download de-identified research record</button>}</div><div className="privacy-banner">Research-only export. Review free text and identifiers before sharing. Routine clinical users do not need JSON files.</div>{result&&<Card title="Technical rule trace"><div className="rule-table">{result.ruleTrace.map(r=><article key={r.ruleId}><div><b>{r.ruleId}</b><span>{r.strength}</span></div><p>{r.conclusion}</p><small>Evidence IDs: {r.evidenceIds.join(", ")}</small></article>)}</div></Card>}<div className="grid three"><Field label="Case ID"><input value={adjudication.caseId} onChange={e=>updateAdjudication("caseId",e.target.value)}/></Field><Field label="Site code"><input value={adjudication.siteCode} onChange={e=>updateAdjudication("siteCode",e.target.value)}/></Field><Field label="Adjudication method"><Select value={adjudication.adjudicationMethod} options={["not-entered","unanimous","majority","third-reviewer","consensus-meeting"] as const} onChange={v=>updateAdjudication("adjudicationMethod",v)}/></Field></div><ReviewerForm title="First independent reviewer" value={adjudication.firstReviewer} onChange={v=>updateAdjudication("firstReviewer",v)}/><ReviewerForm title="Second independent reviewer" value={adjudication.secondReviewer} onChange={v=>updateAdjudication("secondReviewer",v)}/><ReviewerForm title="Adjudicated reference standard" value={adjudication.adjudicated} onChange={v=>updateAdjudication("adjudicated",v)}/></section>}
 </main>
}

function FragmentRow({label:rowLabel,right,left,onRight,onLeft}:{label:string;right:MotorGrade;left:MotorGrade;onRight:(v:MotorGrade)=>void;onLeft:(v:MotorGrade)=>void}){return <><span>{rowLabel}</span><Select value={right} options={grades} onChange={onRight}/><Select value={left} options={grades} onChange={onLeft}/></>}
